        validateDecisions(decisions) {
            var diagEl = document.getElementById('diagnosisInput');
            var lnaEl = document.getElementById('lnaDepthInput');
            var inpersonEl = document.getElementById('inpersonInput');
            var virtualEl = document.getElementById('virtualInput');
            var digitalEl = document.getElementById('digitalInput');
            var sustainmentEl = document.getElementById('sustainmentInput');
            var facultyEl = document.getElementById('facultyInput');
            var segmentEl = document.getElementById('segmentInput');
            var measEl = document.getElementById('measurementInput');
            var guarEl = document.getElementById('guaranteeInput');

            if (diagEl) decisions.diagnosis = diagEl.value;
            if (lnaEl) decisions.lnaDepth = parseInt(lnaEl.value, 10);
            if (inpersonEl) decisions.inperson = parseInt(inpersonEl.value, 10);
            if (virtualEl) decisions.virtual = parseInt(virtualEl.value, 10);
            if (digitalEl) decisions.digital = parseInt(digitalEl.value, 10);
            if (sustainmentEl) decisions.sustainment = parseInt(sustainmentEl.value, 10);
            if (facultyEl) decisions.faculty = facultyEl.value;
            if (segmentEl) decisions.segment = segmentEl.value;
            if (measEl) decisions.measurement = measEl.value;
