        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            try {
                lang = (window.mySimulation && window.mySimulation.lang) ? window.mySimulation.lang : 'en';
            } catch (e) { lang = 'en'; }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefingEn;
            }

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) {
                nameEl.textContent = lang === 'es' ? round.nameEs : round.nameEn;
            }

            var noteEl = document.getElementById('liveLeversNote');
            if (noteEl) {
                var noteKey = 'levers_note_r' + (idx + 1);
                try { noteEl.textContent = window.mySimulation.t(noteKey); } catch (e) {}
            }

            var eventEl = document.getElementById('eventAlert');
            if (eventEl) {
                var eventText = lang === 'es' ? round.eventEs : round.eventEn;
                if (eventText) {
                    eventEl.innerHTML = eventText;
                    eventEl.style.display = 'block';
                } else {
                    eventEl.style.display = 'none';
                }
            }

            this._updateBudgetMeter();
        }

        _updateBudgetMeter() {
            var iEl = document.getElementById('inpersonInput');
            var vEl = document.getElementById('virtualInput');
            var dEl = document.getElementById('digitalInput');
            var sEl = document.getElementById('sustainmentInput');
            if (!iEl || !vEl || !dEl || !sEl) return;
            var inp = parseInt(iEl.value, 10) || 0;
            var vir = parseInt(vEl.value, 10) || 0;
            var dig = parseInt(dEl.value, 10) || 0;
            var sus = parseInt(sEl.value, 10) || 0;
            var total = inp + vir + dig + sus;

            var allocEl = document.getElementById('allocatedDisplay');
            if (allocEl) allocEl.textContent = '€' + total.toLocaleString() + 'k';

            var bar = document.getElementById('budgetMeterBar');
            if (bar) {
                var pct = Math.min(100, Math.round((total / this.BUDGET_CAP) * 100));
                bar.style.width = pct + '%';
                if (total > this.BUDGET_CAP) {
                    bar.classList.add('atlantico-over');
                    bar.style.width = '100%';
                } else {
                    bar.classList.remove('atlantico-over');
                }
            }

            var days = Math.round((inp / this.INPERSON_PER_DAY_K) * 10) / 10;
            var tag = document.getElementById('daysTag');
            if (tag) {
                var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
                tag.textContent = days + ' / ' + this.DAYS_CAP + ' ' + t('days_unit');
                if (days > this.DAYS_CAP) tag.classList.add('atlantico-days-over');
                else tag.classList.remove('atlantico-days-over');
            }
        }

